		#region ValidateAndSave

		protected override ContinueWithSave ValidateAndSave()
		{
			ContinueWithSave result;
			using (new DocketNotificationSubscriberWithWaitCursor(Docket, GetNotificationBuffer()))
			{
				result = CreateTemporaryProductsWithConfirmationNotification();
			}
			return result == ContinueWithSave.No ? result : base.ValidateAndSave();
		}

		#region CreateTemporaryProductsConfirmationNotification

		ContinueWithSave CreateTemporaryProductsWithConfirmationNotification()
		{
			var continueWithSave = ContinueWithSave.No;
			if (Docket.HasInventoryWithStockAndTemporaryProducts)
			{
				var e = new QueryUserYesNoEventArgs(Res.GetString("952940e9-4344-4887-a430-f9c0f1766e10", "New Products Found"), CreateTemporaryProductsConfirmationMessage, false);
				QueryUser(e);
				if (e.Response)
				{
					if (Env.Security.WhsReceiveCreateProductFiles.IsAllowed)
					{
						Docket.CreateProductFiles();
						continueWithSave = ContinueWithSave.Yes;
					}
					else
					{
						Env.Security.ShowError(Env.Security.WhsReceiveCreateProductFiles);
					}
				}
			}
			else
			{
				continueWithSave = ContinueWithSave.Yes;
			}
			return continueWithSave;
		}

