		void OnAllocateLocations(object sender, EventArgs e)
		{
			// cannot move to business because there will be lots of failing tests, cannot do all the fixing in defect WI.
			if (!Docket.IsInDatabase || Docket.HasChanges)
			{
				Globals.Message.ShowError(Res.GetString("9211AB1D-B9B7-47EC-AFDB-4B771E7721D1", "Please save this Receipt before Allocating Locations."));
			}
			else if (Docket.WD_UnloadCompletedTime.IsValid)
			{
				Globals.Message.ShowError(Res.GetString("4a7f3014-f3ad-4800-a302-d4112e529a8d", "Can not allocate location(s) when the unload is completed."));
			}
			else
			{
				using (new DocketNotificationSubscriberWithWaitCursor(Docket, GetNotificationBuffer()))
				{
					ReceiveAllocationHelper.AllocateLocations(new[] { Docket }, Docket.Warehouse, SelectedReceiveLines, Docket.NotificationSubscriber);
				}
			}
		}

