		void CreateProductFiles()
		{
			if (Docket.HasInventoryWithTemporaryProducts)
			{
				using (new DocketNotificationSubscriberWithWaitCursor(Docket, GetNotificationBuffer()))
				{
					Docket.CreateProductFiles();
					if (Docket.HasInventoryWithTemporaryProducts)
					{
						Globals.Message.ShowWarning(Res.GetString("02d11a11-6084-464c-97eb-c01034619f65", "One or more New Products have errors and could not be created. Please correct the errors and try again."));
					}
				}
			}
			else
			{
				Globals.Message.ShowInformation(Res.GetString("13966d0f-02c7-4978-b346-430b4ac3215a", "No New Products were entered, no New Product Files will be created."));
			}
		}

