		#region Create ASN Lines Handler

		void OnCreateASNLines(object sender, EventArgs e)
		{
			if (Docket.AsnLines.Count == 0)
			{
				using (new DocketNotificationSubscriberWithWaitCursor(Docket, GetNotificationBuffer()))
				{
					var context = new DialogDefaultContext(
						new ZGuid("cfba5e60-a0d3-4648-861c-57d5edbb0622"),
						ResString.GetMultilingualString("9ef8c86b-24d1-4cf6-84f5-6ccfd4b07233", "Create ASN Lines"),
						ZMessageBoxButtons.YesNo,
						ZMessageBoxIcon.Warning,
						null,
						showCheckboxOnly: true,
						resultsNotToSave: new[] { ZDialogResult.No });

					var message = ResString.GetMultilingualString("ac70a4e8-5598-47e5-b77b-290d8ab851c5", @"Once the ASN lines are created, it will not be possible to add/update/delete the ASN lines after this.

Do you wish to continue?");

					if (Globals.Message.ShowOrDefault(context, message) == ZDialogResult.Yes)
					{
						Docket.PopulateASNLines();
					}
				}
			}
			else
			{
				Globals.Message.ShowError(Res.GetString("69f780f4-8c21-49c5-afb0-d42d8c4f26ba", "Cannot Overwrite existing ASN Lines. Receive has already started."));
			}
		}

