		#region Cancel Docket Handler

		void OnCancelReactivateDocket(object sender, EventArgs e)
		{
			if (Env.Security.WhsReceiveCancel.IsAllowed)
			{
				if (!Docket.IsCancelled && Docket.CanCancel() != ZString.Empty)
				{
					Globals.Message.ShowError(Docket.CanCancel());
				}
				else
				{
					Docket.CancelReactivateDocket();
					cancelReactivateMenuItem.Text = CancelReactivateReceiveMenuItemText;
				}
			}
			else
			{
				Env.Security.ShowError(Env.Security.WhsReceiveCancel);
			}
		}

		#endregion

		#endregion

		#region Finalise Button

		void FinaliseButton_Click(object sender, EventArgs e)
		{
			if (Env.Security.WhsReceiveFinalise.IsAllowed)
			{
				FinaliseJobFormHelper.FinaliseDocket(Docket, this, GetNotificationBuffer());
			}
			else
			{
				Env.Security.ShowError(Env.Security.WhsReceiveFinalise);
			}
		}

		#endregion

		#region Event Handlers

		void OnWhsReceiveToPrint(object sender, WhsReceiveToPrintEventArgs e)
		{
			ZForm form = null;
			switch (e.DataContext)
			{
				case Core.Constants.DataContext.WhsPalletIDLabels:
					form = new LabelOptionsForm(e.DocketDocument);
					break;
				default:
					e.ContinueToPrint = false;
					break;
			}

			if (form != null)
			{
				e.ContinueToPrint = (ZFormModaliser.ShowDialogAndDispose(form) == DialogResult.Yes);
			}
		}

		void Docket_OnInventoryPrint(object sender, WhsDocumentInventoryEventArgs e)
		{
			using (var form = new WhsDocumentInventoryOptionsForm(e.Options))
			{
				e.ContinueToPrint = ZFormModaliser.ShowDialogAndDispose(form) == DialogResult.Yes;
			}
		}

		void Docket_WarehouseChanged(object sender, EventArgs e)
		{
			SetDockDoorRelatedColumnsVisibility();
			UpdateTaskManagementMenuItem();
		}

		void Docket_TaskPlanningStatusChanged(object sender, EventArgs e) => UpdateTaskManagementMenuItem();

		void Docket_UnloadCompleteTimeChanged(object sender, EventArgs e) => UpdateCompleteUnloadMenuItems();

		#endregion

		#region TestData Button
		internal virtual Action<WhsReceive> OnTestDataButtonClickInternal { get; }

		void TestDataButton_Click(object sender, EventArgs e)
		{
			OnTestDataButtonClickInternal?.Invoke(Docket);
		}
		#endregion

		#region INotifications Members

		void INotifications.Add(INotification notification)
		{
			NotificationsHelper.Add(notification);
		}

		WhsNotificationsHelper NotificationsHelper
		{
			get { return notificationsHelper ?? (notificationsHelper = new WhsNotificationsHelper(Docket)); }
		}

		WhsNotificationsHelper notificationsHelper;

		#endregion

		#region INotificationSubscriberQueryUser

		public void QueryUser(IQueryUserEventArgs e)
		{
			WhsNotificationSubscriberGuiHelper.QueryUser(e);
		}

		#endregion

		#region Implementation

		MultilingualString CancelReactivateReceiveMenuItemText
		{
			get { return Docket.IsCancelled ? ResString.GetMultilingualString("4e27a7d2-77b5-4908-9cf6-72f65d60230c", "Re-Activate {0}", Docket.HumanReadableName) : ResString.GetMultilingualString("9841bb82-c5bb-4400-919f-30126641c178", "Cancel {0}", Docket.HumanReadableName); }
		}

		IEnumerable<WhsInventoryView> SelectedInventoryLines
		{
			get { return SelectedReceiveLines.SelectMany(l => l.Inventory.Cast<WhsInventoryView>()); }
		}

		IEnumerable<WhsReceiveLine> SelectedReceiveLines
		{
			get
			{
				var result = DetailsTabControl.SelectedTab == DetailsTabControl.GetTabPage("LinesTabPage")
								? InventoryGridControl.SelectedInventoryLines
								: inventoryGridUserControl2.SelectedInventoryLines;

				return result;
			}
		}

		public void SelectInventoryLine(ZGuid pK)
		{
			InventoryGridControl.SelectRow(pK);
		}

		void CheckIfNeedValidationAndValidate(WhsReceive docket)
		{
			if (docket.IsJobInError)
			{
				docket.RunPreSaveValidation();
				docket.References.RunPreSaveValidation();
			}
		}

		void LoadDeferred()
		{
			this.OrgWhsFindControl.Focus();
		}

		protected INotifications GetNotificationBuffer()
		{
			INotifications result = this;
#if DEBUG
			if (Globals.IsTest)
			{
				if (TestNotify == null)
				{
					TestNotify = new Environment.Business.Testing.TestNotificationBuffer();
				}

				result = TestNotify;
			}
#endif
			return result;
		}

		#region TaskPlanningStatusMenu

		void UpdateTaskManagementMenuItem()
		{
			taskManagementMenuItem.Visible = Docket.IsTaskManagementEnabled();
			taskManagementMenuItem.Text = Docket.IsUnplanned()
				? ResString.GetMultilingualString("682ddee0-b328-491b-9119-bd09b84c28d2", "Change Task Planning Status To Ready")
				: ResString.GetMultilingualString("1aff7f8d-0868-4469-89ad-1bffb78e66d3", "Change Task Planning Status To Not Ready");
		}

		#endregion

		#region CompleteUnloadMenuItems

		void UpdateCompleteUnloadMenuItems()
		{
			setUnloadCompletedTimeMenuItem.Enabled = BaseMenuItemEnabledCondition && !Docket.WD_UnloadCompletedTime.IsValid;
			clearUnloadCompletedTimeMenuItem.Enabled = BaseMenuItemEnabledCondition && Docket.IsClearingCompletionAllowed;
		}

		#endregion

		IAsyncResult LoadDeferredAsyncResult;
		MenuItem cancelReactivateMenuItem;
		MenuItem taskManagementMenuItem;
		MenuItem setUnloadCompletedTimeMenuItem;
		MenuItem clearUnloadCompletedTimeMenuItem;

		#endregion

		#region Dispose

		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				UnhookEvents();
			}

			base.Dispose(disposing);
		}

		#endregion

		async void ScreenButton_Click(object sender, EventArgs e)
		{
			if (Docket is IScreeningPartyProvider provider)
			{
				await new DeniedPartyScreeningPresentationManager().PerformScreening((ZForm)this, false, !DeniedPartyScreenerAsync.HasExcludedList(Docket.Factory), Docket, () => Docket.DocAddresses.HasChanges);
			}
		}
	}
}

